#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    vector<int> parent(n);
    for (auto &p : parent) cin >> p;
    string s;
    cin >> s;
    vector<vector<int>> children(n);
    for (int i = 1; i < n; i++) children[parent[i]].push_back(i);
    // BFS order from the root 0; processing it backwards handles children before parents
    vector<int> order = {0};
    for (size_t k = 0; k < order.size(); k++)
        for (int v : children[order[k]]) order.push_back(v);
    vector<int> down(n, 1);
    int best = 1;
    for (int k = n - 1; k >= 0; k--) {
        int u = order[k], first = 0, second = 0;
        for (int v : children[u]) {
            if (s[u] == s[v]) continue;
            if (down[v] > first) second = first, first = down[v];
            else if (down[v] > second) second = down[v];
        }
        down[u] = first + 1;
        best = max(best, first + second + 1);
    }
    cout << best << "\n";
}

import java.io.*;
import java.util.*;

public class Main {
    static byte[] buf;
    static int pos;

    static String next() {
        while (buf[pos] <= ' ') pos++;
        int start = pos;
        while (pos < buf.length && buf[pos] > ' ') pos++;
        return new String(buf, start, pos - start);
    }

    static long nextLong() {
        while (buf[pos] <= ' ') pos++;
        boolean neg = buf[pos] == '-';
        if (neg) pos++;
        long r = 0;
        while (pos < buf.length && buf[pos] > ' ') r = r * 10 + (buf[pos++] - '0');
        return neg ? -r : r;
    }

    static int nextInt() {
        return (int) nextLong();
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        int n = nextInt();
        int[] parent = new int[n], childCount = new int[n];
        for (int i = 0; i < n; i++) parent[i] = nextInt();
        String s = next();
        for (int i = 1; i < n; i++) childCount[parent[i]]++;
        // children stored contiguously (CSR) to keep memory flat
        int[] startAt = new int[n + 1];
        for (int i = 0; i < n; i++) startAt[i + 1] = startAt[i] + childCount[i];
        int[] fill = Arrays.copyOf(startAt, n), child = new int[Math.max(n - 1, 1)];
        for (int i = 1; i < n; i++) child[fill[parent[i]]++] = i;
        // BFS order from the root 0; processing it backwards handles children before parents
        int[] order = new int[n];
        int size = 1;
        for (int k = 0; k < size; k++)
            for (int e = startAt[order[k]]; e < startAt[order[k] + 1]; e++) order[size++] = child[e];
        int[] down = new int[n];
        int best = 1;
        for (int k = n - 1; k >= 0; k--) {
            int u = order[k], first = 0, second = 0;
            for (int e = startAt[u]; e < startAt[u + 1]; e++) {
                int v = child[e];
                if (s.charAt(u) == s.charAt(v)) continue;
                if (down[v] > first) {
                    second = first;
                    first = down[v];
                } else if (down[v] > second) second = down[v];
            }
            down[u] = first + 1;
            best = Math.max(best, first + second + 1);
        }
        System.out.println(best);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
)

func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Buffer(make([]byte, 1<<20), 1<<20)
	sc.Split(bufio.ScanWords)
	next := func() int {
		sc.Scan()
		v, _ := strconv.Atoi(sc.Text())
		return v
	}
	n := next()
	parent := make([]int, n)
	for i := range parent {
		parent[i] = next()
	}
	sc.Scan()
	s := sc.Text()
	children := make([][]int, n)
	for i := 1; i < n; i++ {
		children[parent[i]] = append(children[parent[i]], i)
	}
	// BFS order from the root 0; processing it backwards handles children before parents
	order := []int{0}
	for k := 0; k < len(order); k++ {
		order = append(order, children[order[k]]...)
	}
	down := make([]int, n)
	best := 1
	for k := n - 1; k >= 0; k-- {
		u := order[k]
		first, second := 0, 0
		for _, v := range children[u] {
			if s[u] == s[v] {
				continue
			}
			if down[v] > first {
				first, second = down[v], first
			} else if down[v] > second {
				second = down[v]
			}
		}
		down[u] = first + 1
		best = max(best, first+second+1)
	}
	fmt.Println(best)
}
